import Handlebars from 'handlebars';
import ifCond from '../helper/funcs/ifCond.js';

Handlebars.registerHelper('ifCond', ifCond);

describe('ifCond helper', () => {
  it('should return true block for equality (==)', () => {
    const template = Handlebars.compile('{{#ifCond 5 "==" 5}}Equal{{^}}Not Equal{{/ifCond}}');
    const result = template({});
    expect(result).toBe('Equal');
  });

  it('should return false block for inequality (!=)', () => {
    const template = Handlebars.compile('{{#ifCond 5 "!=" 10}}Not Equal{{^}}Equal{{/ifCond}}');
    const result = template({});
    expect(result).toBe('Not Equal');
  });

  it('should handle strict equality (===)', () => {
    const template = Handlebars.compile('{{#ifCond "5" "===" "5"}}Strictly Equal{{^}}Not Strictly Equal{{/ifCond}}');
    const result = template({});
    expect(result).toBe('Strictly Equal');
  });

  it('should handle strict inequality (!==)', () => {
    const template = Handlebars.compile('{{#ifCond 5 "!==" "5"}}Strictly Not Equal{{^}}Strictly Equal{{/ifCond}}');
    const result = template({});
    expect(result).toBe('Strictly Not Equal');
  });

  it('should handle "in" operator for strings', () => {
    const template = Handlebars.compile('{{#ifCond "softpro.ua" "in" "help.softpro.ua,softpro.ua"}}In{{^}}Not In{{/ifCond}}');
    const result = template({});
    expect(result).toBe('In');
  });

  it('should handle "not in" operator for strings', () => {
    const template = Handlebars.compile('{{#ifCond "123" "not in" "help.softpro.ua,softpro.ua"}}Not In{{^}}In{{/ifCond}}');
    const result = template({});
    expect(result).toBe('Not In');
  });

  it('should handle ">" operator', () => {
    const template = Handlebars.compile('{{#ifCond 10 ">" 5}}Greater{{^}}Not Greater{{/ifCond}}');
    const result = template({});
    expect(result).toBe('Greater');
  });

  it('should handle "<" operator', () => {
    const template = Handlebars.compile('{{#ifCond 3 "<" 5}}Lesser{{^}}Not Lesser{{/ifCond}}');
    const result = template({});
    expect(result).toBe('Lesser');
  });

  it('should handle "&&" operator', () => {
    const template = Handlebars.compile('{{#ifCond true "&&" true}}Both True{{^}}Not Both True{{/ifCond}}');
    const result = template({});
    expect(result).toBe('Both True');
  });

  it('should handle "||" operator', () => {
    const template = Handlebars.compile('{{#ifCond false "||" true}}One is True{{^}}None is True{{/ifCond}}');
    const result = template({});
    expect(result).toBe('One is True');
  });

  it('should handle unknown operator and render the inverse block', () => {
    const template = Handlebars.compile('{{#ifCond 5 "unknown" 5}}This will not be displayed{{^}}Unknown Operator{{/ifCond}}');
    const result = template({});
    expect(result).toBe('Unknown Operator');
  });

  it('should handle "&" operator for array intersection', () => {
    const template = Handlebars.compile('{{#ifCond arr1 "&" arr2}}Intersect{{^}}No Intersect{{/ifCond}}');
    const result = template({ arr1: [1, 2, 3], arr2: [3, 4, 5] });
    expect(result).toBe('Intersect');
  });

  it('should handle "!" for no intersection with "&" operator', () => {
    const template = Handlebars.compile('{{#ifCond arr1 "&" arr2}}Intersect{{^}}No Intersect{{/ifCond}}');
    const result = template({ arr1: [1, 2], arr2: [3, 4] });
    expect(result).toBe('No Intersect');
  });

  it('should handle "~" operator for substring match', () => {
    const template = Handlebars.compile('{{#ifCond "softpro" "~" "soft"}}Contains{{^}}Does Not Contain{{/ifCond}}');
    const result = template({});
    expect(result).toBe('Contains');
  });

  it('should handle "!~" operator for no substring match', () => {
    const template = Handlebars.compile('{{#ifCond "softpro" "!~" "help"}}Does Not Contain{{^}}Contains{{/ifCond}}');
    const result = template({});
    expect(result).toBe('Does Not Contain');
  });

  it('should handle "period" operator for date range', () => {
    const template = Handlebars.compile('{{#ifCond "2023-01-01" "period" "2025-01-01"}}Within Period{{^}}Out of Period{{/ifCond}}');
    const result = template({});
    expect(result).toBe('Within Period');
  });

  it('should handle "period" operator for date outside range', () => {
    const template = Handlebars.compile('{{#ifCond "2019-01-01" "period" "2022-01-01"}}Within Period{{^}}Out of Period{{/ifCond}}');
    const result = template({});
    expect(result).toBe('Out of Period');
  });

  it('should handle "in" operator when v1 is an array', () => {
    const template = Handlebars.compile('{{#ifCond arr1 "in" "softpro.ua,help.ua"}}In{{^}}Not In{{/ifCond}}');
    const result = template({ arr1: ["softpro.ua", "help.ua"] });
    expect(result).toBe('In');
  });

  it('should handle "not in" operator when v1 is an array', () => {
    const template = Handlebars.compile('{{#ifCond arr1 "not in" "softpro.ua,help.ua"}}Not In{{^}}In{{/ifCond}}');
    const result = template({ arr1: ["test.ua", "example.ua"] });
    expect(result).toBe('Not In');
  });
});